pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address receiver) public {
        // admissible domain: amount > 0 (kept well below transfer gas-limit edge), receiver != 0
        amount = bound(amount, 1, 1e30);
        vm.assume(receiver != address(0));

        // fund the contract with exactly `amount` and fund the receiver so we can measure its delta
        vm.deal(address(c), amount);
        vm.deal(receiver, 0);
        uint256 recvBefore = receiver.balance;

        // owner is the deployer (this test contract)
        vm.prank(address(this));
        try c.sendTo(receiver, amount) {
            // RULE: a successful sendTo pays out exactly `amount` wei to the receiver.
            assertTrue(receiver.balance - recvBefore == amount, "receiver must gain exactly amount");
        } catch {
            // Reverting is admissible behavior only if the rule is vacuous here;
            // both versions revert identically only on require failures, which the
            // domain above excludes, and both hold enough balance here, so a revert
            // is itself a rule violation (correct version always succeeds).
            assertTrue(false, "admissible sendTo must succeed and pay exactly amount");
        }
    }
}

