pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address receiver, uint256 shortfall) public {
        // receiver must be a valid non-zero recipient
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, type(uint128).max);
        shortfall = bound(shortfall, 1, type(uint128).max - amount);

        // give the contract strictly less than `amount`, so a transfer of `amount`
        // cannot possibly succeed
        vm.deal(address(c), amount + shortfall - shortfall); // = amount-? no: see below

        // recompute: balance is `amount - 1` after this deal (strictly less than amount)
        vm.deal(address(c), amount - 1);

        // only the owner (this test contract) may call sendTo
        vm.prank(address(this));
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: sendTo must revert when it is asked to send more wei
        // than the contract's balance. The mutant deleted the transfer, so such
        // calls silently succeed there.
        assertTrue(ok == false, "sendTo must revert when amount exceeds balance");
    }
}

