pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address receiver, uint96 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner()); // non-owner caller: ownership gate must block any transfer
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);

        // fund the contract so a (buggy) transfer could actually succeed
        vm.deal(address(c), amount);
        uint256 before = address(c).balance;

        vm.prank(actor);
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }

        // General rule: a non-owner call may never move contract funds,
        // regardless of whether it reverts.
        assertTrue(!ok && address(c).balance == before);
    }
}

contract InvMutTest {

    C c;

    constructor(C _c) {
        c = _c;
    }

    function runTest(address receiver, uint amount) public {
        require(receiver != address(0));
        require(amount > 0);
        require(address(this) != tx.origin);

        bool reverted = false;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // A non-owner caller is rejected by C, so the call must revert.
        assert(reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

